_PccuEntry('Oxygen-delivery devices', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Choose the least invasive device that reliably achieves the prescribed saturation target and work-of-breathing goal.','Escalate based on physiology, not device sequence alone.']), _PccuSection('Initial stabilization', <String>['Position airway, suction as needed, apply continuous pulse oximetry and reassess after each device change.','Low-flow nasal cannula is useful for mild oxygen need; simple/venturi masks provide higher or controlled FiOâ‚‚; non-rebreather is a short bridge for severe hypoxemia while definitive support is prepared.']), _PccuSection('Disease-specific treatment / settings', <String>['Humidify prolonged higher-flow oxygen.','Use an oxygen blender when precise FiOâ‚‚ is required, especially in neonates or congenital heart disease.']), _PccuSection('Monitoring', <String>['SpOâ‚‚ trend, respiratory rate, retractions, mental status, heart rate and gas exchange when clinically indicated.']), _PccuSection('Expected response', <String>['Reduced work of breathing and stable saturation on a lower or unchanged FiOâ‚‚.']), _PccuSection('Failure criteria and escalation', <String>['Rising oxygen requirement, exhaustion, apnea, hypercapnia, altered consciousness or poor perfusion.']), _PccuSection('Complications / cautions', <String>['Pressure injury, mucosal drying, delayed escalation and excessive oxygen exposure in susceptible patients.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 Paediatric Life Support; local respiratory therapy policy.'])], 'OXYGEN-DELIVERY DEVICES\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Oxygen-delivery devices pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('High-flow nasal cannula', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Use for hypoxemic respiratory failure or increased work of breathing when low-flow oxygen is insufficient and the child can protect the airway.','HFNC provides heated humidified flow, dead-space washout and variable distending pressure; it is not equivalent to controlled CPAP.']), _PccuSection('Initial stabilization', <String>['Ensure appropriate cannula size with nares not fully occluded.','Common starting flow is approximately 1â€“2 L/kg/min in infants and young children, with local maximums; start FiOâ‚‚ to stabilize then titrate down.','Obtain senior/PCCU review before or soon after initiation in a deteriorating child.']), _PccuSection('Disease-specific treatment / settings', <String>['Treat the cause concurrently: bronchodilator for bronchospasm, antibiotics when bacterial infection is suspected, secretion clearance where appropriate.','Do not use HFNC to delay intubation in apnea, severe encephalopathy, shock or rapidly progressive failure.']), _PccuSection('Monitoring', <String>['Continuous cardiorespiratory monitoring; reassess within 30â€“60 minutes for HR, RR, retractions, FiOâ‚‚ and mental status.']), _PccuSection('Expected response', <String>['Meaningful reduction in tachypnea, retractions and heart rate, with stable/improving oxygenation.']), _PccuSection('Failure criteria and escalation', <String>['No improvement within the planned reassessment window, FiOâ‚‚ requirement rising toward 0.60 or more, recurrent apnea, worsening hypercapnia/acidosis or hemodynamic instability.']), _PccuSection('Complications / cautions', <String>['Air leak, abdominal distension, pressure injury, secretion obstruction and false reassurance.']), _PccuSection('Sources and local verification', <String>['RCH HFNP guideline; institutional bronchiolitis/HFNC pathway; RCUK 2025 PLS.'])], 'HIGH-FLOW NASAL CANNULA\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific High-flow nasal cannula pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('CPAP and BiPAP basics', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['CPAP improves oxygenation and splints airways; BiPAP adds inspiratory pressure support to improve ventilation.','Best suited to a cooperative child with intact airway reflexes and reversible respiratory failure.']), _PccuSection('Initial stabilization', <String>['Use experienced staff, correct interface and continuous monitoring.','Typical editable starting points: CPAP 5â€“8 cmHâ‚‚O; BiPAP EPAP 5â€“8 and IPAP 8â€“12 cmHâ‚‚O, then titrate to response and local protocol.']), _PccuSection('Disease-specific treatment / settings', <String>['Treat agitation non-pharmacologically first; sedation can precipitate airway loss and requires PCCU-level monitoring.','Provide gastric decompression if significant distension.']), _PccuSection('Monitoring', <String>['SpOâ‚‚, respiratory effort, synchrony, leak, skin pressure points, blood gas and hemodynamics.']), _PccuSection('Expected response', <String>['Improved ventilation/oxygenation, lower work of breathing and good patient-device synchrony.']), _PccuSection('Failure criteria and escalation', <String>['Inability to protect airway, copious secretions, recurrent vomiting, worsening acidosis, shock, apnea or intolerance despite optimization.']), _PccuSection('Complications / cautions', <String>['Aspiration, pressure injury, gastric distension, air leak and delayed intubation.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local NIV policy.'])], 'CPAP AND BIPAP BASICS\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific CPAP and BiPAP basics pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Non-invasive ventilation troubleshooting', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Troubleshoot in a fixed sequence: patient, interface, circuit, settings, then disease progression.']), _PccuSection('Initial stabilization', <String>['Check airway patency, secretion burden, mask position, leak, exhalation port, humidification and circuit disconnection.','Confirm trigger sensitivity, rise time, backup rate and inspiratory/expiratory pressures match the child.']), _PccuSection('Disease-specific treatment / settings', <String>['Correct agitation drivers such as hypoxemia, pain, fever, urinary retention and mask discomfort.','Escalate rather than repeatedly increasing pressures when physiology worsens.']), _PccuSection('Monitoring', <String>['Waveforms, delivered tidal volume, leak percentage, SpOâ‚‚, RR, gas exchange and mental status.']), _PccuSection('Expected response', <String>['Improved synchrony and lower work of breathing after the identified issue is corrected.']), _PccuSection('Failure criteria and escalation', <String>['Persistent large leak, poor synchrony, worsening gas, declining consciousness, apnea or shock.']), _PccuSection('Complications / cautions', <String>['Barotrauma, gastric insufflation, pressure injury and delayed invasive ventilation.']), _PccuSection('Sources and local verification', <String>['Local ventilator/NIV manual; RCUK 2025 PLS.'])], 'NON-INVASIVE VENTILATION TROUBLESHOOTING\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Non-invasive ventilation troubleshooting pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Indications for intubation', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Intubate for failure of oxygenation, ventilation or airway protection, or when anticipated deterioration makes controlled airway management safer than rescue intubation.']), _PccuSection('Initial stabilization', <String>['Call experienced airway/PCCU/anesthesia support early and use a checklist.','Preoxygenate with the best tolerated method, optimize hemodynamics and prepare backup airway plans.']), _PccuSection('Disease-specific treatment / settings', <String>['Common triggers: refractory hypoxemia, severe hypercapnic acidosis with fatigue, recurrent apnea, GCS decline, uncontrolled status epilepticus, shock requiring airway control, or upper-airway obstruction.']), _PccuSection('Monitoring', <String>['Continuous ECG, SpOâ‚‚, BP and waveform capnography; document first-pass success and complications.']), _PccuSection('Expected response', <String>['Confirmed tube position with sustained waveform capnography and improved oxygenation/ventilation.']), _PccuSection('Failure criteria and escalation', <String>['Failed first attempt, severe desaturation, hypotension, bradycardia, cannot intubate/cannot oxygenate.']), _PccuSection('Complications / cautions', <String>['Hypoxemia, hypotension, bradycardia, aspiration, esophageal or mainstem intubation and airway trauma.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; Difficult Airway Society pediatric guidance; local RSI protocol.'])], 'INDICATIONS FOR INTUBATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Indications for intubation pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Pediatric rapid-sequence intubation', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Pediatric RSI is a high-risk team procedure. Use a checklist, role assignment, physiologic optimization and explicit plans Aâ€“D.']), _PccuSection('Initial approach / settings', <String>['Preoxygenate with the most effective tolerated method; use apneic oxygenation when feasible.','Prepare appropriately sized cuffed tubes, video/direct laryngoscope, bougie/stylet, suction, BVM with PEEP, rescue supraglottic airway and surgical airway equipment.','Estimate cuffed ETT size age/4 + 3.5 mm for children over 1 year, but prepare one size above/below and use length/weight references in infants.']), _PccuSection('Medication doses / settings', <String>['Ketamine 1â€“2 mg/kg IV is commonly used for induction when hemodynamic stability is desired; lower dose may be appropriate in shock.','Rocuronium 1â€“1.2 mg/kg IV provides rapid paralysis. Succinylcholine 1â€“2 mg/kg IV may be used when not contraindicated.','Use atropine selectively rather than routinely; dose and indication should follow current PALS/local policy.']), _PccuSection('Monitoring intervals', <String>['Continuous ECG, SpO2, BP cycling rapidly and waveform capnography. Confirm tube with sustained ETCO2, chest rise, bilateral air entry and imaging as appropriate.']), _PccuSection('Failure criteria and escalation', <String>['Falling saturation, failed first attempt, cannot intubate/cannot oxygenate, hemodynamic collapse or absent capnography. Move promptly through the difficult-airway plan.']), _PccuSection('Complications / cautions', <String>['Peri-intubation hypoxemia, hypotension, bradycardia, aspiration, esophageal/mainstem intubation and barotrauma. Begin post-intubation analgesia/sedation immediately.']), _PccuSection('Sources and local verification', <String>['Current PALS/RCUK pediatric life support; institutional difficult-airway and RSI protocol.'])], 'PEDIATRIC RAPID-SEQUENCE INTUBATION\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Initial ventilator settings by disease', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Start with disease-pattern settings, then individualize using ideal body weight, gas exchange, mechanics and hemodynamics.']), _PccuSection('Initial stabilization', <String>['Confirm ETT position, obtain chest movement and waveform capnography, then set lung-protective ventilation.','Use the dedicated ventilator calculator for editable starting suggestions.']), _PccuSection('Disease-specific treatment / settings', <String>['Obstructive disease: lower RR and long expiratory time. Restrictive/ARDS: lower tidal volume and adequate PEEP. Neuromuscular disease: support minute ventilation and secretion clearance.']), _PccuSection('Monitoring', <String>['Peak/plateau pressures, expiratory flow returning to baseline, tidal volume, ETCOâ‚‚, gas, SpOâ‚‚ and BP.']), _PccuSection('Expected response', <String>['Acceptable oxygenation/ventilation without excessive pressure, auto-PEEP or hemodynamic compromise.']), _PccuSection('Failure criteria and escalation', <String>['Rising pressures, worsening acidosis, persistent hypoxemia, air trapping, hypotension or dyssynchrony.']), _PccuSection('Complications / cautions', <String>['Volutrauma, barotrauma, atelectrauma, oxygen toxicity and ventilator-induced hypotension.']), _PccuSection('Sources and local verification', <String>['PALICC-2 pediatric ARDS guidance; RCUK 2025 PLS; local ventilation protocol.'])], 'INITIAL VENTILATOR SETTINGS BY DISEASE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Initial ventilator settings by disease pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Ventilator alarm troubleshooting', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Respond to the patient first, not the alarm; disconnect and hand-ventilate if the child is unstable and equipment failure is possible.']), _PccuSection('Initial stabilization', <String>['High pressure: consider DOPEâ€”displacement, obstruction, pneumothorax, equipmentâ€”plus bronchospasm and biting.','Low pressure/volume: circuit disconnect, cuff leak, extubation or large airway leak.']), _PccuSection('Disease-specific treatment / settings', <String>['Pass suction catheter to assess patency; examine chest symmetry and tube depth; use bedside ultrasound/chest radiograph as indicated.']), _PccuSection('Monitoring', <String>['SpOâ‚‚, ETCOâ‚‚ waveform, airway pressures, delivered/exhaled volumes and hemodynamics.']), _PccuSection('Expected response', <String>['Alarm resolves with stable gas exchange and identified cause corrected.']), _PccuSection('Failure criteria and escalation', <String>['Cannot ventilate, absent ETCOâ‚‚, unilateral breath sounds with instability, tension pneumothorax signs or persistent severe hypoxemia.']), _PccuSection('Complications / cautions', <String>['Delayed recognition of tube displacement, pneumothorax or circuit failure.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local ventilator troubleshooting policy.'])], 'VENTILATOR ALARM TROUBLESHOOTING\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Ventilator alarm troubleshooting pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Weaning and extubation-readiness checklist', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Extubation readiness requires improvement in disease, adequate gas exchange on modest support, airway protection and a feasible post-extubation plan.']), _PccuSection('Initial stabilization', <String>['Review sedation, secretions, cough strength, airway edema risk, hemodynamics and neuromuscular function.','Perform a spontaneous breathing trial according to local protocol when appropriate.']), _PccuSection('Disease-specific treatment / settings', <String>['Consider dexamethasone before extubation when high risk for airway edema; ensure rescue equipment and NIV/HFNC plan are ready.']), _PccuSection('Monitoring', <String>['Work of breathing, tidal volume, RR, gas, secretion burden, leak assessment where used and neurologic status.']), _PccuSection('Expected response', <String>['Comfortable spontaneous breathing with stable gas exchange and hemodynamics.']), _PccuSection('Failure criteria and escalation', <String>['Marked tachypnea, apnea, rising COâ‚‚, poor cough, excessive secretions or hemodynamic instability during trial.']), _PccuSection('Complications / cautions', <String>['Extubation failure, upper-airway obstruction, atelectasis and withdrawal/agitation.']), _PccuSection('Sources and local verification', <String>['Local extubation protocol; RCUK 2025 PLS.'])], 'WEANING AND EXTUBATION-READINESS CHECKLIST\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Weaning and extubation-readiness checklist pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Post-extubation stridor', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Suspect laryngeal edema when inspiratory stridor and increased work of breathing occur after extubation.']), _PccuSection('Initial stabilization', <String>['Position, humidified oxygen, minimize agitation and assess severity immediately.','Prepare reintubation equipment early in severe or progressive obstruction.']), _PccuSection('Disease-specific treatment / settings', <String>['Nebulized epinephrine is commonly used for moderate/severe stridor; corticosteroid treatment depends on timing and local protocol.','Heliox may be a temporary bridge where available.']), _PccuSection('Monitoring', <String>['Continuous SpOâ‚‚, air entry, stridor at rest, retractions, mental status and response after each treatment.']), _PccuSection('Expected response', <String>['Reduced stridor and work of breathing with stable oxygenation.']), _PccuSection('Failure criteria and escalation', <String>['Silent chest, fatigue, cyanosis, altered consciousness, poor air entry or recurrent severe symptoms after epinephrine.']), _PccuSection('Complications / cautions', <String>['Rapid airway loss and delayed reintubation.']), _PccuSection('Sources and local verification', <String>['Local post-extubation airway pathway; RCUK 2025 PLS.'])], 'POST-EXTUBATION STRIDOR\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Post-extubation stridor pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Difficult airway escalation', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Declare difficulty early, limit repeated attempts and prioritize oxygenation over tracheal intubation.']), _PccuSection('Initial stabilization', <String>['Call anesthesia/ENT/PCCU and bring the difficult-airway cart.','Use the most experienced operator, optimize position and move deliberately through Plan A/B/C/D.']), _PccuSection('Disease-specific treatment / settings', <String>['Consider video laryngoscopy, bougie/stylet and supraglottic airway.','In cannot-intubate/cannot-oxygenate physiology, proceed to the institutionâ€™s emergency front-of-neck access pathway.']), _PccuSection('Monitoring', <String>['Time, attempts, saturation nadir, ventilation between attempts and hemodynamics.']), _PccuSection('Expected response', <String>['Oxygenation maintained and airway secured with the least traumatic method.']), _PccuSection('Failure criteria and escalation', <String>['Two failed attempts by experienced operators, inability to mask ventilate or falling saturation despite rescue maneuvers.']), _PccuSection('Complications / cautions', <String>['Airway trauma, edema, hypoxic arrest and task fixation.']), _PccuSection('Sources and local verification', <String>['Difficult Airway Society pediatric algorithm; local difficult-airway plan.'])], 'DIFFICULT AIRWAY ESCALATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Difficult airway escalation pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Accidental extubation response', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Treat as an airway emergency; determine immediately whether the child can oxygenate and ventilate without the tube.']), _PccuSection('Initial stabilization', <String>['Call for help, stop feeds, position airway, suction and provide bag-mask ventilation with PEEP as needed.','Do not blindly advance a partially displaced tube.']), _PccuSection('Disease-specific treatment / settings', <String>['Reintubate when respiratory failure persists or airway protection is inadequate; prepare full RSI and difficult-airway backup.']), _PccuSection('Monitoring', <String>['SpOâ‚‚, ETCOâ‚‚, HR, BP and chest movement; document event and contributing factors.']), _PccuSection('Expected response', <String>['Stable spontaneous breathing or successful reintubation with confirmed ETCOâ‚‚.']), _PccuSection('Failure criteria and escalation', <String>['Inability to ventilate, severe desaturation, bradycardia or hemodynamic collapse.']), _PccuSection('Complications / cautions', <String>['Hypoxic injury, aspiration and repeated displacement.']), _PccuSection('Sources and local verification', <String>['Local unplanned extubation policy; RCUK 2025 PLS.'])], 'ACCIDENTAL EXTUBATION RESPONSE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Accidental extubation response pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Severe asthma', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Severe asthma is defined by persistent respiratory distress, poor air entry, hypoxemia, exhaustion or inadequate response to initial inhaled bronchodilator therapy. A quiet chest can represent critical obstruction.','Consider alternative/complicating diagnoses: anaphylaxis, foreign body, pneumonia, pneumothorax, cardiac disease and vocal-cord dysfunction.']), _PccuSection('Initial approach / settings', <String>['Continuous cardiorespiratory monitoring, frequent respiratory examination and early PCCU/RT involvement.','Give oxygen to the prescribed saturation target; use inhaled salbutamol/albuterol promptly and add ipratropium during the initial severe phase.','Give systemic corticosteroid early; do not delay for imaging.']), _PccuSection('Medication doses / settings', <String>['Continuous nebulized salbutamol/albuterol is institution-specific; common pediatric pathways use weight-banded continuous delivery with close potassium, glucose, lactate and rhythm monitoring.','Ipratropium 250â€“500 micrograms nebulized every 20 minutes for three doses is commonly used in severe exacerbations, depending on age/weight and local protocol.','Magnesium sulfate IV 25â€“50 mg/kg over about 20â€“30 minutes (commonly maximum 2 g) for severe disease not responding to initial therapy.','Aminophylline, IV salbutamol/terbutaline and ketamine are rescue therapies requiring PCCU/pharmacy protocol and toxicity monitoring.']), _PccuSection('Respiratory support', <String>['HFNC may improve oxygenation but does not reliably relieve severe airflow obstruction; excessive flow can worsen dynamic hyperinflation in some patients.','NIV may be considered in a cooperative child with preserved airway reflexes and close expert monitoring; do not delay intubation in exhaustion, altered consciousness, refractory hypoxemia or shock.']), _PccuSection('Monitoring intervals', <String>['Reassess continuously during initial stabilization and at least every 15â€“30 minutes after major therapy changes.','Trend air entry, speech, accessory muscle use, mental status, heart rate, SpO2, blood gas when indicated, potassium, glucose and lactate.']), _PccuSection('Failure criteria and escalation', <String>['Worsening fatigue, bradycardia, altered mental status, rising PaCO2 with acidosis, recurrent apnea, hemodynamic compromise or refractory hypoxemia.','Prepare for a physiologically difficult intubation with senior airway/PCCU/anesthesia support and a post-intubation ventilation plan.']), _PccuSection('Complications / cautions', <String>['Dynamic hyperinflation, auto-PEEP, barotrauma, hypotension, hypokalemia, lactic acidosis and tachyarrhythmia.','After intubation use low respiratory rate, long expiratory time, cautious tidal volume and permissive hypercapnia when appropriate; accept incomplete normalization to avoid air trapping.']), _PccuSection('Sources and local verification', <String>['CPS acute asthma guidance; institutional severe asthma pathway; current PALS/PCCU protocol.'])], 'SEVERE ASTHMA\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Status asthmaticus', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Severe asthma is defined by persistent respiratory distress, poor air entry, hypoxemia, exhaustion or inadequate response to initial inhaled bronchodilator therapy. A quiet chest can represent critical obstruction.','Consider alternative/complicating diagnoses: anaphylaxis, foreign body, pneumonia, pneumothorax, cardiac disease and vocal-cord dysfunction.']), _PccuSection('Initial approach / settings', <String>['Continuous cardiorespiratory monitoring, frequent respiratory examination and early PCCU/RT involvement.','Give oxygen to the prescribed saturation target; use inhaled salbutamol/albuterol promptly and add ipratropium during the initial severe phase.','Give systemic corticosteroid early; do not delay for imaging.']), _PccuSection('Medication doses / settings', <String>['Continuous nebulized salbutamol/albuterol is institution-specific; common pediatric pathways use weight-banded continuous delivery with close potassium, glucose, lactate and rhythm monitoring.','Ipratropium 250â€“500 micrograms nebulized every 20 minutes for three doses is commonly used in severe exacerbations, depending on age/weight and local protocol.','Magnesium sulfate IV 25â€“50 mg/kg over about 20â€“30 minutes (commonly maximum 2 g) for severe disease not responding to initial therapy.','Aminophylline, IV salbutamol/terbutaline and ketamine are rescue therapies requiring PCCU/pharmacy protocol and toxicity monitoring.']), _PccuSection('Respiratory support', <String>['HFNC may improve oxygenation but does not reliably relieve severe airflow obstruction; excessive flow can worsen dynamic hyperinflation in some patients.','NIV may be considered in a cooperative child with preserved airway reflexes and close expert monitoring; do not delay intubation in exhaustion, altered consciousness, refractory hypoxemia or shock.']), _PccuSection('Monitoring intervals', <String>['Reassess continuously during initial stabilization and at least every 15â€“30 minutes after major therapy changes.','Trend air entry, speech, accessory muscle use, mental status, heart rate, SpO2, blood gas when indicated, potassium, glucose and lactate.']), _PccuSection('Failure criteria and escalation', <String>['Worsening fatigue, bradycardia, altered mental status, rising PaCO2 with acidosis, recurrent apnea, hemodynamic compromise or refractory hypoxemia.','Prepare for a physiologically difficult intubation with senior airway/PCCU/anesthesia support and a post-intubation ventilation plan.']), _PccuSection('Complications / cautions', <String>['Dynamic hyperinflation, auto-PEEP, barotrauma, hypotension, hypokalemia, lactic acidosis and tachyarrhythmia.','After intubation use low respiratory rate, long expiratory time, cautious tidal volume and permissive hypercapnia when appropriate; accept incomplete normalization to avoid air trapping.']), _PccuSection('Sources and local verification', <String>['CPS acute asthma guidance; institutional severe asthma pathway; current PALS/PCCU protocol.'])], 'STATUS ASTHMATICUS\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Bronchiolitis requiring HFNC', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['HFNC is considered when bronchiolitis causes persistent hypoxemia or moderate/severe work of breathing despite suction, positioning and low-flow oxygen.','Routine bronchodilators, corticosteroids and antibiotics are not indicated unless another diagnosis or a documented trial supports them.']), _PccuSection('Initial approach / settings', <String>['Gentle nasal suction, minimal handling, hydration assessment and enteral/NG feeding when safe.','Select cannula that does not fully occlude the nares. Common initial flow is 1â€“2 L/kg/min with institutional maximums; titrate FiO2 to the local saturation target.']), _PccuSection('Monitoring intervals', <String>['Continuous SpO2/heart rate and documented reassessment within 30â€“60 minutes of initiation or escalation.','Track respiratory rate, retractions, apnea, mental status, FiO2, feeding tolerance and hydration.']), _PccuSection('Expected response', <String>['Lower heart and respiratory rates, reduced retractions and stable oxygenation without rising FiO2.']), _PccuSection('Failure criteria and escalation', <String>['No meaningful improvement within 30â€“60 minutes, recurrent apnea, exhaustion, rising CO2/acidosis, FiO2 around 0.60 or greater, or hemodynamic instability.','Escalate to CPAP/NIV or intubation based on physiology and local PCCU capability.']), _PccuSection('Complications / cautions', <String>['Air leak, abdominal distension, skin injury, delayed escalation and fluid overload.']), _PccuSection('Sources and local verification', <String>['CPS bronchiolitis guidance; RCH HFNC guidance; local respiratory therapy pathway.'])], 'BRONCHIOLITIS REQUIRING HFNC\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Severe pneumonia', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Consider bacterial, viral, aspiration and complicated pneumonia; assess for effusion, empyema, necrosis and sepsis.']), _PccuSection('Initial stabilization', <String>['Oxygen/respiratory support, cultures when feasible before antibiotics, prompt empiric antimicrobials and fluid/perfusion assessment.','Use ultrasound or chest imaging when complications are suspected.']), _PccuSection('Disease-specific treatment / settings', <String>['Antibiotic choice should follow age, immunization, local resistance, MRSA risk and aspiration context.','Drain significant complicated effusion/empyema with respiratory/surgical/interventional input.']), _PccuSection('Monitoring', <String>['SpOâ‚‚, work of breathing, perfusion, lactate, urine output, inflammatory markers and imaging trajectory when complicated.']), _PccuSection('Expected response', <String>['Falling oxygen need, improved work of breathing and perfusion within the expected interval.']), _PccuSection('Failure criteria and escalation', <String>['Escalating support, shock, rising lactate, enlarging effusion, air leak or multiorgan dysfunction.']), _PccuSection('Complications / cautions', <String>['Empyema, necrotizing pneumonia, pneumothorax, ARDS and septic shock.']), _PccuSection('Sources and local verification', <String>['IDSA/PIDS pediatric CAP guidance; local antimicrobial and empyema pathways.'])], 'SEVERE PNEUMONIA\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Severe pneumonia pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Pediatric ARDS', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Use PALICC-2 concepts: acute pulmonary disease with hypoxemia and new infiltrates not fully explained by cardiac failure or fluid overload. Severity and trajectory should be assessed using oxygenation index/oxygen saturation index when invasively ventilated.']), _PccuSection('Initial approach / settings', <String>['Treat the cause, use lung-protective ventilation and avoid unnecessary positive fluid balance after shock is corrected.','Use ideal/predicted body weight for tidal-volume targets. Start approximately 6â€“8 mL/kg for preserved compliance and 4â€“6 mL/kg when compliance is poor, then titrate to pressures and gas exchange.','Use PEEP/FiO2 strategy appropriate to severity; limit plateau and driving pressure according to local PALICC-based protocol.']), _PccuSection('Monitoring intervals', <String>['Continuous oxygenation/hemodynamics; serial gases, ventilator waveforms, plateau pressure, compliance, fluid balance and OI/OSI.','Reassess after every major PEEP, tidal-volume or recruitment change.']), _PccuSection('Failure criteria and escalation', <String>['Progressive OI/OSI, severe hypoxemia despite optimized PEEP, injurious pressures, worsening shock or inability to ventilate.','Consider prone positioning, neuromuscular blockade for severe dyssynchrony, inhaled pulmonary vasodilator as rescue, and early ECMO-center discussion when refractory.']), _PccuSection('Complications / cautions', <String>['Ventilator-induced lung injury, air leak, hemodynamic compromise, sedation/NMBA complications, delirium and critical illness weakness.']), _PccuSection('Sources and local verification', <String>['PALICC-2 pediatric ARDS guidance; local ventilation and ECMO referral pathways.'])], 'PEDIATRIC ARDS\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Croup requiring advanced airway support', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Severe croup includes stridor at rest with marked retractions, fatigue, hypoxemia or reduced air entry.']), _PccuSection('Initial stabilization', <String>['Keep the child calm, provide dexamethasone and nebulized epinephrine, and involve anesthesia/ENT/PCCU early.','Avoid upsetting examinations or procedures until the airway team is ready.']), _PccuSection('Disease-specific treatment / settings', <String>['Prepare a smaller-than-age-predicted ETT because of subglottic edema; use the most experienced airway operator.']), _PccuSection('Monitoring', <String>['Continuous SpOâ‚‚, stridor, air entry, mental status and recurrence after epinephrine.']), _PccuSection('Expected response', <String>['Sustained reduction in stridor and work of breathing after observation.']), _PccuSection('Failure criteria and escalation', <String>['Exhaustion, cyanosis, altered consciousness, poor air entry or recurrent severe obstruction.']), _PccuSection('Complications / cautions', <String>['Rapid airway obstruction, post-intubation edema and unplanned extubation.']), _PccuSection('Sources and local verification', <String>['RCH croup guideline; local difficult-airway protocol.'])], 'CROUP REQUIRING ADVANCED AIRWAY SUPPORT\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Croup requiring advanced airway support pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Upper-airway obstruction', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Differentiate croup, anaphylaxis, epiglottitis/bacterial tracheitis, foreign body, abscess and post-extubation edema.']), _PccuSection('Initial stabilization', <String>['Call anesthesia/ENT/PCCU early, keep the child upright and calm, and avoid airway agitation.','Give condition-specific therapy such as IM epinephrine for anaphylaxis or nebulized epinephrine/dexamethasone for croup.']), _PccuSection('Disease-specific treatment / settings', <String>['Do not force throat examination when epiglottitis or critical obstruction is suspected.','Prepare for controlled airway management in the operating room/PICU when feasible.']), _PccuSection('Monitoring', <String>['Stridor, voice, drooling, air entry, mental status, SpOâ‚‚ and hemodynamics.']), _PccuSection('Expected response', <String>['Improving air entry and reduced stridor without fatigue.']), _PccuSection('Failure criteria and escalation', <String>['Silent obstruction, cyanosis, bradycardia, altered consciousness or inability to maintain oxygenation.']), _PccuSection('Complications / cautions', <String>['Complete obstruction, aspiration and traumatic airway attempts.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local ENT/difficult-airway pathway.'])], 'UPPER-AIRWAY OBSTRUCTION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Upper-airway obstruction pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Aspiration', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Aspiration may cause acute obstruction, chemical pneumonitis, bacterial pneumonia or ARDS.']), _PccuSection('Initial stabilization', <String>['Suction visible material, support oxygenation/ventilation and evaluate for foreign body or ongoing aspiration.','Bronchoscopy is indicated when particulate obstruction or foreign body is suspected.']), _PccuSection('Disease-specific treatment / settings', <String>['Antibiotics are not automatically required for uncomplicated chemical pneumonitis; use when bacterial infection is suspected or established.']), _PccuSection('Monitoring', <String>['SpOâ‚‚, work of breathing, fever, gas exchange and radiographic progression when severe.']), _PccuSection('Expected response', <String>['Improving oxygenation and respiratory effort over hours with supportive care.']), _PccuSection('Failure criteria and escalation', <String>['Persistent focal obstruction, worsening oxygen requirement, shock or evolving ARDS.']), _PccuSection('Complications / cautions', <String>['Pneumonia, abscess, ARDS and recurrent aspiration.']), _PccuSection('Sources and local verification', <String>['Local aspiration/foreign-body and antimicrobial guidance.'])], 'ASPIRATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Aspiration pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Pulmonary hemorrhage', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Treat frank airway bleeding with hypoxemia as a life-threatening airway and circulation emergency.']), _PccuSection('Initial stabilization', <String>['Call PCCU/respiratory/hematology, give high-concentration oxygen, secure airway if needed and correct coagulopathy.','Use large-bore suction and isolate the bleeding lung when anatomically possible.']), _PccuSection('Disease-specific treatment / settings', <String>['Ventilation may require higher PEEP; bronchoscopy/interventional radiology/surgery may be required.','Review anticoagulants, platelet count, coagulation, vasculitis and cardiac causes.']), _PccuSection('Monitoring', <String>['Hemoglobin, coagulation, gas exchange, airway pressures, hemodynamics and bleeding volume.']), _PccuSection('Expected response', <String>['Bleeding slows, oxygenation stabilizes and transfusion requirement falls.']), _PccuSection('Failure criteria and escalation', <String>['Ongoing large-volume bleeding, refractory hypoxemia, shock or airway obstruction.']), _PccuSection('Complications / cautions', <String>['Asphyxia, severe anemia, ARDS and recurrent hemorrhage.']), _PccuSection('Sources and local verification', <String>['Local massive hemoptysis/pulmonary hemorrhage protocol.'])], 'PULMONARY HEMORRHAGE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Pulmonary hemorrhage pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Neuromuscular respiratory failure', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Look for weak cough, bulbar dysfunction, shallow breathing, paradoxical movement and declining vital capacity rather than relying on SpOâ‚‚ alone.']), _PccuSection('Initial stabilization', <String>['Involve neurology/respiratory/PCCU, support secretion clearance and monitor ventilation.','Use NIV early in selected cooperative patients without major bulbar dysfunction.']), _PccuSection('Disease-specific treatment / settings', <String>['Avoid excessive oxygen without ventilation assessment because hypercapnia may worsen unnoticed.','Plan intubation before profound fatigue or secretion-related collapse.']), _PccuSection('Monitoring', <String>['Serial gas/ETCOâ‚‚, cough strength, secretion burden, vital capacity or negative inspiratory force where feasible.']), _PccuSection('Expected response', <String>['Improved ventilation and secretion clearance with stable bulbar function.']), _PccuSection('Failure criteria and escalation', <String>['Rising COâ‚‚, weak cough, recurrent atelectasis, aspiration, inability to clear secretions or reduced consciousness.']), _PccuSection('Complications / cautions', <String>['Mucus plugging, aspiration, atelectasis and difficult weaning.']), _PccuSection('Sources and local verification', <String>['Local neuromuscular respiratory-failure guidance.'])], 'NEUROMUSCULAR RESPIRATORY FAILURE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Neuromuscular respiratory failure pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Apnea and hypoventilation', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Identify central, obstructive, medication-related, seizure-related, metabolic and neuromuscular causes.']), _PccuSection('Initial stabilization', <String>['Stimulate, position airway, provide bag-mask ventilation as needed, check glucose and attach cardiorespiratory monitoring.','Administer naloxone when opioid toxicity is plausible without delaying ventilation.']), _PccuSection('Disease-specific treatment / settings', <String>['Obtain targeted gas, electrolytes, toxicology and neurologic evaluation; use NIV or intubation according to airway protection and recurrence.']), _PccuSection('Monitoring', <String>['Apnea frequency, ETCOâ‚‚, gas, oxygenation, neurologic status and medication exposure.']), _PccuSection('Expected response', <String>['No recurrent apnea and normalized ventilation after cause-directed treatment.']), _PccuSection('Failure criteria and escalation', <String>['Recurrent/prolonged apnea, rising COâ‚‚, bradycardia, aspiration or altered consciousness.']), _PccuSection('Complications / cautions', <String>['Hypoxic injury, aspiration and cardiorespiratory arrest.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local apnea pathway.'])], 'APNEA AND HYPOVENTILATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Apnea and hypoventilation pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
