_PccuEntry('Status epilepticus', 'Neurologic Emergencies', <_PccuSection>[_PccuSection('Clinical overview', <String>['Convulsive status epilepticus is a seizure lasting 5 minutes or recurrent seizures without recovery. Treat while evaluating glucose, sodium, calcium, magnesium, infection, trauma, toxins and adherence.']), _PccuSection('Medication doses / settings', <String>['First-line: lorazepam IV 0.1 mg/kg (max 4 mg), midazolam IN/IM/buccal 0.2 mg/kg (local maximum), or diazepam according to route-specific protocol. Count prehospital benzodiazepines to avoid excessive stacking.','If ongoing after adequate benzodiazepine therapy, give one second-line agent promptly: levetiracetam 40â€“60 mg/kg IV (common max 4.5 g), fosphenytoin 20 mg PE/kg (max 1.5 g PE), or valproate 20â€“40 mg/kg when not contraindicated.','Refractory status requires PCCU/neurology, airway preparation, continuous EEG and anesthetic infusion protocol such as midazolam; ketamine or pentobarbital may be used in specialist pathways.']), _PccuSection('Monitoring intervals', <String>['Continuous cardiorespiratory monitoring, bedside glucose immediately, serial neurologic examination and temperature.','Obtain EEG urgently if paralysis is used or nonconvulsive status is suspected.']), _PccuSection('Failure criteria and escalation', <String>['Seizure persists after benzodiazepine plus appropriate second-line medication, recurrent seizures without recovery, respiratory failure, shock or concern for raised ICP.']), _PccuSection('Complications / cautions', <String>['Respiratory depression, hypotension, aspiration, hyperthermia, rhabdomyolysis and medication-specific dysrhythmia/hepatotoxicity.']), _PccuSection('Sources and local verification', <String>['CPS convulsive status epilepticus guidance; current PALS and institutional neurology/PCCU pathway.'])], 'STATUS EPILEPTICUS\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Refractory status epilepticus', 'Neurologic Emergencies', <_PccuSection>[_PccuSection('Clinical overview', <String>['Refractory status persists despite an adequate benzodiazepine and second-line antiseizure medication.']), _PccuSection('Initial stabilization', <String>['Call neurology/PCCU/anesthesia, prepare intubation and continuous EEG.','Search for toxic, infectious, autoimmune, metabolic and structural causes while seizures are treated.']), _PccuSection('Disease-specific treatment / settings', <String>['Continuous midazolam is commonly used; ketamine or pentobarbital may be used under specialist protocols.','Consider pyridoxine in infants when clinically appropriate with resuscitation capability.']), _PccuSection('Monitoring', <String>['Continuous EEG, BP, ventilation, temperature, electrolytes, CK, lactate and drug concentrations where relevant.']), _PccuSection('Expected response', <String>['Electrographic seizure suppression with stable organ function and an etiologic plan.']), _PccuSection('Failure criteria and escalation', <String>['Breakthrough seizures, escalating infusion requirements, hypotension or multiorgan toxicity.']), _PccuSection('Complications / cautions', <String>['Prolonged ventilation, infection, ileus, hypotension, withdrawal and neurologic injury.']), _PccuSection('Sources and local verification', <String>['ILAE/AES guidance; local refractory-status protocol.'])], 'REFRACTORY STATUS EPILEPTICUS\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Refractory status epilepticus pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Raised intracranial pressure', 'Neurologic Emergencies', <_PccuSection>[_PccuSection('Clinical overview', <String>['Suspect raised ICP with declining consciousness, focal deficits, abnormal pupils, repeated vomiting, hypertension/bradycardia, irregular respirations or posturing. Normal vital signs do not exclude it.']), _PccuSection('Initial approach / settings', <String>['Call PCCU/neurosurgery, elevate head 30 degrees, keep neck midline, avoid fever, hypoxemia, hypotension and hypo-osmolar fluids.','Secure the airway when necessary using a hemodynamically protective plan; target normoxia and generally normocapnia. Brief controlled hyperventilation is only a temporizing measure for impending herniation.']), _PccuSection('Medication doses / settings', <String>['Hypertonic saline 3% 2â€“5 mL/kg IV over 10â€“20 minutes is commonly used for acute intracranial hypertension; repeat/infusion strategy requires specialist protocol.','Mannitol 0.5â€“1 g/kg IV may be considered when hemodynamics and renal status permit.','Treat seizures promptly and maintain adequate analgesia/sedation.']), _PccuSection('Monitoring intervals', <String>['Frequent GCS/pupils, BP, sodium/osmolality, urine output and ventilation. Reassess immediately after osmotherapy.']), _PccuSection('Failure criteria and escalation', <String>['Progressive pupillary change, posturing, refractory ICP, worsening CT findings or hemodynamic instability.']), _PccuSection('Complications / cautions', <String>['Hypotension, hypernatremia, osmotic diuresis, renal injury and rebound ICP. Avoid routine corticosteroids in traumatic brain injury.']), _PccuSection('Sources and local verification', <String>['CPS acute head trauma guidance; Brain Trauma Foundation pediatric severe TBI guidance; local neurocritical care protocol.'])], 'RAISED INTRACRANIAL PRESSURE\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Traumatic brain injury', 'Neurologic Emergencies', <_PccuSection>[_PccuSection('Clinical overview', <String>['Traumatic brain injury is a time-sensitive neurocritical-care problem requiring stabilization and parallel etiologic evaluation.','Avoid hypoxemia, hypotension, hypoglycemia and fever.']), _PccuSection('Initial stabilization', <String>['ABCDE, bedside glucose, focused neurologic examination including pupils and GCS, and seizure treatment when present.','Engage neurology/PCCU and obtain urgent imaging or EEG according to stability and suspected cause.']), _PccuSection('Disease-specific treatment / settings', <String>['Treat the reversible cause of traumatic brain injury while maintaining cerebral perfusion and ventilation.','Use age/weight-specific medication pathways and avoid delays for nonessential testing.']), _PccuSection('Monitoring', <String>['Serial GCS/pupils, BP, oxygenation, ventilation, glucose/electrolytes and seizure activity.']), _PccuSection('Expected response', <String>['Stable or improving neurologic examination with cause-specific control.']), _PccuSection('Failure criteria and escalation', <String>['Declining GCS, new focal signs, refractory seizures, abnormal pupils, apnea or hemodynamic instability.']), _PccuSection('Complications / cautions', <String>['Aspiration, secondary brain injury, seizures, dysautonomia and treatment toxicity.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local neurology/neurocritical-care pathway.'])], 'TRAUMATIC BRAIN INJURY\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Traumatic brain injury pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
