_PccuEntry('Sedation assessment', 'Neurologic Emergencies', <_PccuSection>[_PccuSection('Clinical overview', <String>['Sedation assessment is a time-sensitive neurocritical-care problem requiring stabilization and parallel etiologic evaluation.','Avoid hypoxemia, hypotension, hypoglycemia and fever.']), _PccuSection('Initial stabilization', <String>['ABCDE, bedside glucose, focused neurologic examination including pupils and GCS, and seizure treatment when present.','Engage neurology/PCCU and obtain urgent imaging or EEG according to stability and suspected cause.']), _PccuSection('Disease-specific treatment / settings', <String>['Treat the reversible cause of sedation assessment while maintaining cerebral perfusion and ventilation.','Use age/weight-specific medication pathways and avoid delays for nonessential testing.']), _PccuSection('Monitoring', <String>['Serial GCS/pupils, BP, oxygenation, ventilation, glucose/electrolytes and seizure activity.']), _PccuSection('Expected response', <String>['Stable or improving neurologic examination with cause-specific control.']), _PccuSection('Failure criteria and escalation', <String>['Declining GCS, new focal signs, refractory seizures, abnormal pupils, apnea or hemodynamic instability.']), _PccuSection('Complications / cautions', <String>['Aspiration, secondary brain injury, seizures, dysautonomia and treatment toxicity.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local neurology/neurocritical-care pathway.'])], 'SEDATION ASSESSMENT\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Sedation assessment pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Delirium screening', 'Neurologic Emergencies', <_PccuSection>[_PccuSection('Clinical overview', <String>['Delirium screening is a time-sensitive neurocritical-care problem requiring stabilization and parallel etiologic evaluation.','Avoid hypoxemia, hypotension, hypoglycemia and fever.']), _PccuSection('Initial stabilization', <String>['ABCDE, bedside glucose, focused neurologic examination including pupils and GCS, and seizure treatment when present.','Engage neurology/PCCU and obtain urgent imaging or EEG according to stability and suspected cause.']), _PccuSection('Disease-specific treatment / settings', <String>['Treat the reversible cause of delirium screening while maintaining cerebral perfusion and ventilation.','Use age/weight-specific medication pathways and avoid delays for nonessential testing.']), _PccuSection('Monitoring', <String>['Serial GCS/pupils, BP, oxygenation, ventilation, glucose/electrolytes and seizure activity.']), _PccuSection('Expected response', <String>['Stable or improving neurologic examination with cause-specific control.']), _PccuSection('Failure criteria and escalation', <String>['Declining GCS, new focal signs, refractory seizures, abnormal pupils, apnea or hemodynamic instability.']), _PccuSection('Complications / cautions', <String>['Aspiration, secondary brain injury, seizures, dysautonomia and treatment toxicity.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local neurology/neurocritical-care pathway.'])], 'DELIRIUM SCREENING\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Delirium screening pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Sedation by procedure', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('How to use this section', <String>['Choose the procedure first, then define whether the child needs analgesia, anxiolysis/sedation, immobility, or all three. Paralysis never substitutes for analgesia or sedation.','Before moderate/deep sedation: confirm weight, allergies, airway risk, fasting status when applicable, IV access/rescue plan, monitoring, suction, oxygen/BVM and a clinician capable of airway rescue.']), _PccuSection('Lumbar puncture', <String>['Analgesia: topical anesthetic when time allows plus local lidocaine infiltration. Add comfort positioning, distraction and child-life support when available.','Sedation: a cooperative older child may need none or minimal anxiolysis; for deeper sedation, ketamine is useful because it supplies both dissociation and analgesia. Propofol provides sedation but no analgesia and requires a separate analgesic/local-anesthetic plan.','Paralysis: not indicated for routine lumbar puncture.']), _PccuSection('Intubation / RSI', <String>['Analgesia/sympathetic blunting: fentanyl may be used selectively and slowly when physiology permits; do not delay an urgent airway to give it.','Induction: ketamine is commonly favored when hypotension/bronchospasm is a concern; propofol is rapid but can markedly lower blood pressure; etomidate is hemodynamically stable but has adrenal-suppression considerations.','Paralysis: rocuronium 1â€“1.2 mg/kg IV is a common RSI choice; succinylcholine 1â€“2 mg/kg IV is an alternative when no contraindication exists. Start post-intubation analgesia/sedation immediately.']), _PccuSection('Traumatic brain injury / raised ICP', <String>['Primary goals are prevention of hypoxemia and hypotension, adequate analgesia, avoidance of agitation/coughing, normocapnia unless temporarily treating impending herniation, and preservation of the neurologic examination when feasible.','Ketamine is not automatically contraindicated in acute brain injury and can be attractive when blood pressure is tenuous. Fentanyl provides analgesia; midazolam or short-acting sedatives may be added when needed. Propofol can reduce cerebral metabolic demand but hypotension is dangerous and prolonged/high-dose pediatric ICU infusion should be avoided.','Neuromuscular blockade is reserved for a defined indication such as RSI, severe ventilator dyssynchrony or refractory ICP crises after adequate analgesia/sedation. It obscures the motor examination and seizure activity.']), _PccuSection('Lines, chest tube and other painful bedside procedures', <String>['Use local anesthetic whenever possible. For very painful procedures, ketamine is often a useful single-agent option; opioid plus sedative combinations can work but increase respiratory-depression risk.','Chest-tube insertion generally requires strong analgesia plus sedation when time and physiology permit. For unstable children, titrate small doses and prioritize resuscitation.']), _PccuSection('Imaging / non-painful immobility', <String>['Use the least depth necessary. Dexmedetomidine or propofol may provide immobility depending on duration, airway risk and local credentialing; neither substitutes for analgesia when the procedure is painful.','Reassess continuously because children can unintentionally progress to deeper sedation.']), _PccuSection('Core monitoring', <String>['Continuous pulse oximetry; frequent non-invasive blood pressure; ECG and capnography for IV moderate/deep sedation when available. Record drug, dose, route, time and response.','Have age/size-appropriate airway equipment and reversal/rescue drugs immediately available.']), _PccuSection('Sources', <String>['Canadian Paediatric Society: Recommendations for procedural sedation in infants, children and adolescents.','SCCM PANDEM pediatric pain, agitation and neuromuscular-blockade guideline; local PCCU/anesthesia formulary remains the dose authority.'])], 'SEDATION BY PROCEDURE\n- Define procedure, pain, desired sedation depth and need for immobility.\n- Use local/regional analgesia whenever possible.\n- Choose one primary sedative strategy and titrate to effect.\n- Paralysis requires established analgesia + sedation and a defined indication.\n- Continuous monitoring and airway rescue capability are mandatory for deep sedation.'),
_PccuEntry('Intubation / RSI sedation', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Preparation', <String>['Assign airway roles and plans Aâ€“D; optimize oxygenation, perfusion and glucose; prepare suction, BVM/PEEP, supraglottic rescue and waveform capnography.','Anticipate peri-intubation hypotension. In shock, reduce sedative dose rather than giving a full healthy-child induction dose automatically.']), _PccuSection('Analgesia / pretreatment', <String>['Fentanyl 1â€“2 mcg/kg IV slow may be considered when analgesia or sympathetic blunting is desired and blood pressure allows. Rapid/high doses can cause apnea, hypotension and chest-wall rigidity.','Routine lidocaine pretreatment to prevent ICP rise is not recommended; follow local neurocritical-care protocol for special circumstances.']), _PccuSection('Induction options', <String>['Ketamine 1â€“2 mg/kg IV. Often preferred for bronchospasm or relative hemodynamic instability; use a lower dose in catecholamine-depleted shock.','Propofol 1â€“2 mg/kg IV in a hemodynamically stable child; consider substantially reduced dosing when preload/BP is marginal. Provides no analgesia.','Etomidate 0.3 mg/kg IV is a rapid hemodynamically stable alternative; consider adrenal-suppression concerns, especially in septic shock.']), _PccuSection('Paralysis', <String>['Rocuronium 1â€“1.2 mg/kg IV for RSI. Longer duration than succinylcholine; ensure post-intubation sedation is ordered before paralysis wears off.','Succinylcholine 1â€“2 mg/kg IV when appropriate. Avoid with known/suspected hyperkalemia-risk neuromuscular disease, major burns/crush after the risk window, malignant-hyperthermia susceptibility and other local contraindications.']), _PccuSection('Immediately after tube placement', <String>['Confirm sustained waveform ETCO2, then secure tube and reassess depth/position, oxygenation, ventilation and blood pressure.','Begin analgesia and sedation immediately. Paralysis does not provide amnesia, anxiolysis or pain control.']), _PccuSection('Sources', <String>['PALS/local pediatric difficult-airway pathway; CPS procedural sedation principles; SCCM PANDEM principles for analgesia, sedation and NMBA use.'])], 'PEDIATRIC RSI\n- Preoxygenate + optimize perfusion.\n- Induction: ketamine 1â€“2 mg/kg IV OR propofol 1â€“2 mg/kg IV if hemodynamically stable OR etomidate 0.3 mg/kg IV when appropriate.\n- Paralysis: rocuronium 1â€“1.2 mg/kg IV; succinylcholine 1â€“2 mg/kg IV when not contraindicated.\n- Confirm with waveform ETCO2.\n- Start post-intubation analgesia/sedation immediately.'),
_PccuEntry('TBI sedation & neuroprotection', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Neuroprotective priorities', <String>['Avoid hypoxemia and hypotension; maintain age-appropriate cerebral perfusion, normothermia, normal glucose and ventilation targets. Elevate head midline when not contraindicated and treat seizures promptly.','Sedation should prevent agitation, coughing and ventilator dyssynchrony without unnecessarily eliminating serial neurologic assessment.']), _PccuSection('Analgesia', <String>['Fentanyl 0.5â€“1 mcg/kg IV slow bolus is a common starting analgesic range; repeat/titrate carefully to physiology. Continuous infusion commonly begins around 0.5â€“1 mcg/kg/hr and is titrated per local PICU protocol.','Avoid large rapid opioid boluses that cause hypotension or chest-wall rigidity.']), _PccuSection('Sedation choices', <String>['Ketamine: 1â€“2 mg/kg IV for induction; low-dose bolus/infusion can be used as an adjunct. Current practice no longer treats ketamine as universally contraindicated solely because of TBI; preserve blood pressure and use neurocritical-care guidance.','Midazolam: 0.05â€“0.1 mg/kg IV titrated; useful for sedation/seizure control but can lower BP, accumulate and obscure the neurologic exam.','Propofol: rapid onset/offset and decreases cerebral metabolic demand, but can cause significant hypotension. Avoid prolonged/high-dose continuous infusion for pediatric ICU sedation because of propofol infusion syndrome risk.']), _PccuSection('Paralysis', <String>['Use only for a defined indication such as RSI, refractory ICP crisis or severe ventilator dyssynchrony after adequate sedation/analgesia.','Rocuronium is useful for RSI; cisatracurium may be useful for ongoing blockade when organ-independent elimination is desired. Use train-of-four plus clinical assessment and the lowest effective NMBA dose.']), _PccuSection('Red flags', <String>['New pupillary asymmetry, falling GCS, Cushing physiology, recurrent bradycardia/apnea, refractory hypoxemia/hypotension or seizures require immediate senior/neurosurgical/PCCU escalation.']), _PccuSection('Sources', <String>['CPS acute head trauma guidance; SCCM PANDEM; local pediatric neurocritical-care/TBI pathway.'])], 'TBI SEDATION / NEUROPROTECTION\n- Prevent hypoxemia + hypotension.\n- Analgesia first; avoid agitation/coughing.\n- Ketamine is not automatically contraindicated in TBI; choose agent by physiology.\n- Avoid prolonged/high-dose propofol infusion in children.\n- NMBA only for a defined indication after deep analgesia/sedation; monitor blockade.'),
_PccuEntry('Lumbar puncture sedation', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Before sedation', <String>['Confirm indication and contraindications, including concern for mass effect/herniation, clinically important coagulopathy, local infection and cardiorespiratory instability. Do not sedate an unstable child simply to complete the LP.','Use topical anesthetic if time allows, local lidocaine, comfort positioning, distraction and caregiver/child-life support.']), _PccuSection('Minimal / no sedation', <String>['Older cooperative children may tolerate LP with excellent local anesthesia and coaching alone. Nitrous oxide or minimal anxiolysis may be an option where credentialing/equipment are available.']), _PccuSection('Ketamine option', <String>['Ketamine 1â€“1.5 mg/kg IV is a common initial dissociative sedation dose; additional 0.25â€“0.5 mg/kg IV doses may be titrated as needed under a procedural-sedation protocol.','Provides analgesia plus dissociation. Watch for vomiting, hypersalivation, laryngospasm, apnea and recovery agitation; airway rescue equipment is mandatory.']), _PccuSection('Propofol option', <String>['Propofol 0.5â€“1 mg/kg IV titrated to effect can provide rapid deep sedation where appropriately credentialed. It has no analgesic effect, so maintain local anesthesia/analgesia.','Important adverse effects are apnea/airway obstruction and hypotension; continuous capnography is strongly preferred for deep IV sedation.']), _PccuSection('Opioid + benzodiazepine', <String>['Fentanyl plus midazolam may provide analgesia/anxiolysis but has synergistic respiratory-depressant effects and often less reliable immobility than dissociative sedation. Titrate slowly with full monitoring.']), _PccuSection('Paralysis', <String>['Neuromuscular blockade is not indicated for routine lumbar puncture. If immobility cannot be safely achieved with sedation, stop and escalate to anesthesia/PCCU rather than paralyzing a spontaneously breathing child for an LP.']), _PccuSection('Sources', <String>['CPS procedural sedation statement; TREKK procedural sedation resources; local sedation credentialing and LP policy.'])], 'LUMBAR PUNCTURE SEDATION\n- Local/topical anesthesia + comfort measures for every child when feasible.\n- Ketamine: 1â€“1.5 mg/kg IV initially, then 0.25â€“0.5 mg/kg IV titrated as needed under local protocol.\n- Propofol: 0.5â€“1 mg/kg IV titrated; provides sedation, not analgesia.\n- Avoid routine NMBA for LP.\n- Full deep-sedation monitoring and airway rescue capability.'),
_PccuEntry('Procedural sedation', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Safety framework', <String>['Match drug choice to the procedure: painful versus non-painful, duration, need for immobility, airway risk, hemodynamics and practitioner familiarity.','At least one clinician must be capable of advanced airway rescue; have suction, oxygen, BVM, airway adjuncts, emergency drugs and appropriate monitoring immediately available.']), _PccuSection('Monitoring', <String>['Continuous pulse oximetry and frequent non-invasive BP; ECG and end-tidal CO2 should be available for IV moderate/deep sedation. Record vitals, drug dose/time, depth and adverse events.','Continue monitoring through recovery until the child has returned to baseline.']), _PccuSection('Medication strategy', <String>['Ketamine supplies both dissociation and analgesia. Propofol is a sedative-hypnotic without analgesia. Opioid + benzodiazepine combinations increase respiratory-depression risk.','Avoid stacking repeated drugs without reassessing effect. Use one primary strategy and titrate deliberately.']), _PccuSection('Escalation / anesthesia involvement', <String>['Consider anesthesia for difficult airway, significant cardiorespiratory disease, severe OSA, very young/high-risk infants, ASA III or higher, active significant illness, increased ICP concern, or when local sedation criteria are not met.']), _PccuSection('Sources', <String>['Canadian Paediatric Society procedural sedation position statement; TREKK procedural sedation; local institutional sedation policy.'])], 'PROCEDURAL SEDATION\n- Define procedure + target depth.\n- Confirm airway/resuscitation readiness and monitoring.\n- Choose one primary sedative strategy and titrate.\n- Treat pain separately when using a non-analgesic sedative.\n- Monitor through recovery to baseline.'),
_PccuEntry('Continuous analgesia', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Continuous analgesia should use goal-directed, regularly reassessed sedation and analgesia rather than unstructured medication stacking.']), _PccuSection('Initial stabilization', <String>['Define pain/sedation target and reversible causes of distress.','Use non-pharmacologic measures and family presence where appropriate.']), _PccuSection('Disease-specific treatment / settings', <String>['Prefer analgesia-first when pain is present; use validated scales and daily de-escalation.','Neuromuscular blockade requires deep sedation, analgesia and eye/skin/pressure care.']), _PccuSection('Monitoring', <String>['Validated pain/sedation/delirium/withdrawal scores, respiratory status, BP and bowel/bladder function.']), _PccuSection('Expected response', <String>['Comfort and safety at target without excessive sedation.']), _PccuSection('Failure criteria and escalation', <String>['Escalating doses, delirium, withdrawal, hypotension or inability to awaken when expected.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, immobility and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation protocol.'])], 'CONTINUOUS ANALGESIA\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Continuous analgesia pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Continuous sedation', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Set a patient-specific sedation target and prioritize analgesia-first, protocolized sedation with regular assessment.']), _PccuSection('Medication doses / settings', <String>['Common options include dexmedetomidine, midazolam, ketamine and opioid-based analgosedation; exact starting/titration doses require local PCCU/pharmacy protocol.','Avoid prolonged propofol infusion in critically ill children because of propofol infusion syndrome risk.','Minimize benzodiazepine exposure when feasible to reduce delirium risk.']), _PccuSection('Monitoring intervals', <String>['Use a validated sedation scale at regular intervals, pain scoring, delirium screening and daily review of ongoing need.','Monitor hemodynamics, ventilation, drug accumulation, organ function and withdrawal risk.']), _PccuSection('Failure criteria and escalation', <String>['Agitation threatening devices despite addressing pain/delirium, oversedation, hypotension/bradycardia or escalating dose without effect.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation and withdrawal protocols.'])], 'CONTINUOUS SEDATION\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Neuromuscular blockade', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Use neuromuscular blockade only for a defined indication and shortest necessary duration. It does not provide analgesia, amnesia or sedation.']), _PccuSection('Initial approach / settings', <String>['Ensure adequate analgesia and sedation before and throughout paralysis; document indication and target depth.','Use the lowest effective NMBA dose, daily reassessment and eye care.']), _PccuSection('Monitoring intervals', <String>['Clinical assessment plus train-of-four when appropriate; continuous ventilation and hemodynamic monitoring.','Use EEG when seizure detection is required because clinical movement is suppressed.']), _PccuSection('Failure criteria and escalation', <String>['Unexpected movement, prolonged weakness, inability to monitor sedation, corneal injury or ventilator/physiologic deterioration.']), _PccuSection('Complications / cautions', <String>['Awareness, critical illness weakness, corneal injury, pressure injury and masked seizures.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local NMBA protocol.'])], 'NEUROMUSCULAR BLOCKADE\\n- Apply ABCDE stabilization and confirm measured weight.\\n- Use the disease-specific treatment, monitoring and escalation plan above.\\n- Verify all doses, concentrations and settings with current local PCCU/pharmacy protocols.\\n- Reassess after every intervention and escalate for failure criteria.'),
_PccuEntry('Withdrawal prevention', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Withdrawal prevention should use goal-directed, regularly reassessed sedation and analgesia rather than unstructured medication stacking.']), _PccuSection('Initial stabilization', <String>['Define pain/sedation target and reversible causes of distress.','Use non-pharmacologic measures and family presence where appropriate.']), _PccuSection('Disease-specific treatment / settings', <String>['Prefer analgesia-first when pain is present; use validated scales and daily de-escalation.','Neuromuscular blockade requires deep sedation, analgesia and eye/skin/pressure care.']), _PccuSection('Monitoring', <String>['Validated pain/sedation/delirium/withdrawal scores, respiratory status, BP and bowel/bladder function.']), _PccuSection('Expected response', <String>['Comfort and safety at target without excessive sedation.']), _PccuSection('Failure criteria and escalation', <String>['Escalating doses, delirium, withdrawal, hypotension or inability to awaken when expected.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, immobility and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation protocol.'])], 'WITHDRAWAL PREVENTION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Withdrawal prevention pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Delirium', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Delirium should use goal-directed, regularly reassessed sedation and analgesia rather than unstructured medication stacking.']), _PccuSection('Initial stabilization', <String>['Define pain/sedation target and reversible causes of distress.','Use non-pharmacologic measures and family presence where appropriate.']), _PccuSection('Disease-specific treatment / settings', <String>['Prefer analgesia-first when pain is present; use validated scales and daily de-escalation.','Neuromuscular blockade requires deep sedation, analgesia and eye/skin/pressure care.']), _PccuSection('Monitoring', <String>['Validated pain/sedation/delirium/withdrawal scores, respiratory status, BP and bowel/bladder function.']), _PccuSection('Expected response', <String>['Comfort and safety at target without excessive sedation.']), _PccuSection('Failure criteria and escalation', <String>['Escalating doses, delirium, withdrawal, hypotension or inability to awaken when expected.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, immobility and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation protocol.'])], 'DELIRIUM\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Delirium pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Sedation weaning', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Sedation weaning should use goal-directed, regularly reassessed sedation and analgesia rather than unstructured medication stacking.']), _PccuSection('Initial stabilization', <String>['Define pain/sedation target and reversible causes of distress.','Use non-pharmacologic measures and family presence where appropriate.']), _PccuSection('Disease-specific treatment / settings', <String>['Prefer analgesia-first when pain is present; use validated scales and daily de-escalation.','Neuromuscular blockade requires deep sedation, analgesia and eye/skin/pressure care.']), _PccuSection('Monitoring', <String>['Validated pain/sedation/delirium/withdrawal scores, respiratory status, BP and bowel/bladder function.']), _PccuSection('Expected response', <String>['Comfort and safety at target without excessive sedation.']), _PccuSection('Failure criteria and escalation', <String>['Escalating doses, delirium, withdrawal, hypotension or inability to awaken when expected.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, immobility and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation protocol.'])], 'SEDATION WEANING\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Sedation weaning pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Fentanyl', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Potent short-acting opioid for analgesia, procedural adjunct and ventilated-patient analgosedation. It does not provide reliable amnesia by itself.']), _PccuSection('Typical pediatric IV reference doses', <String>['Analgesic/procedural bolus: 0.5â€“1 mcg/kg IV slowly; selected intubation contexts may use 1â€“2 mcg/kg IV slowly.','Continuous infusion: commonly 0.5â€“3 mcg/kg/hr, titrated to pain/sedation target and local protocol.']), _PccuSection('Important adverse effects', <String>['Respiratory depression/apnea, bradycardia, hypotension, ileus, urinary retention, nausea/pruritus, tolerance and withdrawal.','Rapid or high-dose administration can cause chest-wall rigidity; give IV boluses slowly and be prepared to ventilate/paralyze if severe.']), _PccuSection('Pearls', <String>['Use lower/titrated dosing when combined with benzodiazepines, propofol or other sedatives. Renal dysfunction generally affects fentanyl less than morphine metabolites, but prolonged infusion can still accumulate.']), _PccuSection('Sources', <String>['SCCM PANDEM principles; local pediatric critical-care formulary/pharmacy.'])], 'FENTANYL\n- Bolus 0.5â€“1 mcg/kg IV slow; selected RSI contexts 1â€“2 mcg/kg IV slow.\n- Infusion commonly 0.5â€“3 mcg/kg/hr.\n- Watch apnea, hypotension/bradycardia, ileus/urinary retention, tolerance/withdrawal and chest-wall rigidity.\n- Titrate to validated pain/sedation target.'),
_PccuEntry('Morphine', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Morphine: opioid analgesic with histamine release and active metabolites; adjust in renal dysfunction.','Always prescribe analgesia and sedation before or with paralysis.']), _PccuSection('Initial stabilization', <String>['Confirm indication, weight, airway plan, hemodynamics and concurrent sedatives.','Use a validated sedation/pain target and the lowest effective dose.']), _PccuSection('Disease-specific treatment / settings', <String>['Use local formulary bolus/infusion doses and smart-pump concentrations.','Daily reassessment and protocolized weaning reduce oversedation and withdrawal.']), _PccuSection('Monitoring', <String>['Continuous cardiorespiratory monitoring; pain/sedation score, BP, ventilation, bowel/bladder function and drug-specific adverse effects.']), _PccuSection('Expected response', <String>['Comfort, synchrony and procedure tolerance at the predefined target.']), _PccuSection('Failure criteria and escalation', <String>['Inadequate comfort, hypotension, respiratory depression, delirium, prolonged paralysis or escalating requirements.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, ileus, hypotension and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation formulary.'])], 'MORPHINE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Morphine pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Hydromorphone', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Hydromorphone: potent opioid useful when morphine is unsuitable; verify equianalgesic conversion.','Always prescribe analgesia and sedation before or with paralysis.']), _PccuSection('Initial stabilization', <String>['Confirm indication, weight, airway plan, hemodynamics and concurrent sedatives.','Use a validated sedation/pain target and the lowest effective dose.']), _PccuSection('Disease-specific treatment / settings', <String>['Use local formulary bolus/infusion doses and smart-pump concentrations.','Daily reassessment and protocolized weaning reduce oversedation and withdrawal.']), _PccuSection('Monitoring', <String>['Continuous cardiorespiratory monitoring; pain/sedation score, BP, ventilation, bowel/bladder function and drug-specific adverse effects.']), _PccuSection('Expected response', <String>['Comfort, synchrony and procedure tolerance at the predefined target.']), _PccuSection('Failure criteria and escalation', <String>['Inadequate comfort, hypotension, respiratory depression, delirium, prolonged paralysis or escalating requirements.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, ileus, hypotension and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation formulary.'])], 'HYDROMORPHONE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Hydromorphone pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Ketamine', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Dissociative anesthetic with analgesia, amnesia and bronchodilation; useful for painful procedures, RSI and as a PICU sedation adjunct.','Airway reflexes are often preserved but not guaranteed; apnea, obstruction and laryngospasm can occur.']), _PccuSection('Typical pediatric IV reference doses', <String>['Procedural dissociation: 1â€“1.5 mg/kg IV initially; additional 0.25â€“0.5 mg/kg IV titrated as needed under a sedation protocol.','RSI induction: 1â€“2 mg/kg IV; reduce in catecholamine-depleted shock.','Analgesic/sub-dissociative bolus: 0.1â€“0.3 mg/kg IV. PICU adjunct infusions vary widely; a common range is about 5â€“20 mcg/kg/min (0.3â€“1.2 mg/kg/hr), titrated per local protocol.']), _PccuSection('Important adverse effects', <String>['Hypersalivation, nausea/vomiting, recovery agitation/hallucinations, nystagmus, hypertension/tachycardia; uncommon laryngospasm or apnea.','In profoundly catecholamine-depleted shock, direct myocardial depressant effects can become clinically important despite ketamineâ€™s usual sympathomimetic profile.']), _PccuSection('TBI / ICP pearl', <String>['Ketamine is not considered universally contraindicated solely because of traumatic brain injury. In an unstable child, preservation of blood pressure may be advantageous; coordinate with neurocritical-care goals.']), _PccuSection('Sources', <String>['CPS procedural sedation principles; TREKK procedural sedation; SCCM PANDEM; local PCCU/anesthesia formulary.'])], 'KETAMINE\n- Procedure: 1â€“1.5 mg/kg IV; top-ups 0.25â€“0.5 mg/kg IV.\n- RSI: 1â€“2 mg/kg IV; reduce in catecholamine-depleted shock.\n- Analgesic: 0.1â€“0.3 mg/kg IV.\n- PICU adjunct infusion commonly ~5â€“20 mcg/kg/min per local protocol.\n- Watch secretions, vomiting, emergence reaction, laryngospasm/apnea and hemodynamic response.'),
_PccuEntry('Midazolam', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Benzodiazepine providing anxiolysis, amnesia, sedation and anticonvulsant effect. It does not provide analgesia.']), _PccuSection('Typical pediatric IV reference doses', <String>['Bolus: 0.05â€“0.1 mg/kg IV slowly, titrated to effect; use smaller doses when combined with opioids or in hemodynamic instability.','Continuous infusion: commonly 0.05â€“0.2 mg/kg/hr in ventilated children, titrated to sedation target and local protocol.']), _PccuSection('Important adverse effects', <String>['Respiratory depression/apnea, hypotension, paradoxical agitation, delirium association, tolerance, accumulation with prolonged infusion and withdrawal.']), _PccuSection('Pearls', <String>['Respiratory depression is synergistic with opioids. Consider minimizing benzodiazepine exposure when alternatives meet the sedation goal.']), _PccuSection('Sources', <String>['SCCM PANDEM; local pediatric critical-care formulary/pharmacy.'])], 'MIDAZOLAM\n- Bolus commonly 0.05â€“0.1 mg/kg IV slow.\n- Infusion commonly 0.05â€“0.2 mg/kg/hr.\n- No analgesia.\n- Watch apnea, hypotension, paradoxical agitation, delirium, accumulation and withdrawal.'),
_PccuEntry('Dexmedetomidine', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Alpha-2 agonist producing cooperative sedation and sympatholysis with relatively limited respiratory depression. Useful for ventilated patients and selected non-painful procedures.']), _PccuSection('Typical pediatric infusion reference', <String>['Continuous infusion is commonly 0.2â€“1.5 mcg/kg/hr. Many PICUs avoid a loading bolus because it can produce abrupt bradycardia/hypotension; follow local protocol.']), _PccuSection('Important adverse effects', <String>['Bradycardia, hypotension, transient hypertension with loading, reduced cardiac output in susceptible patients and withdrawal/rebound symptoms after prolonged use.']), _PccuSection('Pearls', <String>['Does not reliably provide adequate analgesia for painful procedures; pair with a pain strategy when pain is present.']), _PccuSection('Sources', <String>['SCCM PANDEM; local pediatric critical-care formulary/pharmacy.'])], 'DEXMEDETOMIDINE\n- Infusion commonly 0.2â€“1.5 mcg/kg/hr.\n- Loading bolus often avoided in PICU.\n- Minimal respiratory depression compared with many sedatives but watch bradycardia/hypotension.\n- Add analgesia for painful procedures.'),
_PccuEntry('Propofol', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Rapid sedative-hypnotic with fast onset/offset and antiemetic properties. It has no analgesic effect.']), _PccuSection('Typical pediatric IV reference doses', <String>['Procedural/deep sedation: 0.5â€“1 mg/kg IV titrated in small increments; some anesthesia inductions use 1â€“2 mg/kg IV depending on age and physiology.','Reduce substantially in hypovolemia, shock or myocardial dysfunction. Continuous dosing should follow anesthesia/PICU protocol rather than a generic bedside range.']), _PccuSection('Important adverse effects', <String>['Apnea, airway obstruction, loss of protective reflexes, hypotension, bradycardia and pain on injection.','Prolonged/high-dose pediatric ICU infusion is associated with propofol infusion syndrome; avoid using propofol as routine prolonged continuous PICU sedation.']), _PccuSection('TBI pearl', <String>['Can rapidly reduce cerebral metabolic demand but the benefit is lost if systemic hypotension compromises cerebral perfusion. Use only with close hemodynamic control.']), _PccuSection('Sources', <String>['CPS procedural sedation principles; pediatric anesthesia/PICU practice; local formulary.'])], 'PROPOFOL\n- Procedural/deep sedation: commonly 0.5â€“1 mg/kg IV titrated.\n- Anesthesia induction often 1â€“2 mg/kg IV in stable physiology.\n- No analgesia.\n- Watch apnea/airway obstruction and hypotension.\n- Avoid routine prolonged/high-dose continuous PICU infusion in children because of PRIS risk.'),
_PccuEntry('Etomidate', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Ultra-short hypnotic used mainly for induction because it usually causes less cardiovascular depression than propofol. It has no analgesic effect.']), _PccuSection('Typical pediatric IV reference dose', <String>['Induction: 0.3 mg/kg IV is a commonly used reference dose; titrate/verify with local airway protocol.']), _PccuSection('Important adverse effects', <String>['Myoclonus, nausea/vomiting, pain on injection and transient adrenal suppression from 11Î²-hydroxylase inhibition.','Because adrenal suppression may matter in septic shock, many pediatric critical-care teams prefer an alternative induction agent in sepsis; follow local practice.']), _PccuSection('Sources', <String>['Local pediatric RSI/anesthesia formulary; current pediatric critical-care practice.'])], 'ETOMIDATE\n- Induction commonly 0.3 mg/kg IV.\n- Hemodynamically stable hypnotic; no analgesia.\n- Watch myoclonus and adrenal suppression; consider alternatives in septic shock per local protocol.'),
_PccuEntry('Rocuronium', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Nondepolarizing neuromuscular blocker. Provides paralysis onlyâ€”no analgesia, sedation or amnesia.']), _PccuSection('Typical pediatric IV reference doses', <String>['RSI: 1â€“1.2 mg/kg IV.','Maintenance bolus: commonly 0.1â€“0.2 mg/kg IV. Continuous infusion ranges vary by age and institution; titrate to clinical effect/train-of-four under a PICU protocol.']), _PccuSection('Important adverse effects', <String>['Prolonged weakness/paralysis, tachycardia in some patients, rare anaphylaxis and awareness if sedation is inadequate.','Duration can be prolonged in organ dysfunction and after repeated dosing.']), _PccuSection('Monitoring', <String>['Confirm deep analgesia/sedation before and throughout paralysis. Use the lowest effective dose and train-of-four in conjunction with clinical assessment.']), _PccuSection('Sources', <String>['SCCM PANDEM; current local RSI/PICU formulary.'])], 'ROCURONIUM\n- RSI: 1â€“1.2 mg/kg IV.\n- Maintenance bolus commonly 0.1â€“0.2 mg/kg IV.\n- Paralysis only: establish analgesia + sedation first.\n- Use lowest effective dose; TOF + clinical assessment for ongoing blockade.'),
_PccuEntry('Succinylcholine', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Depolarizing neuromuscular blocker with very rapid onset and short duration. Provides paralysis only.']), _PccuSection('Typical pediatric IV reference dose', <String>['RSI/rescue airway: 1â€“2 mg/kg IV. IM dosing is institution-specific and should follow the emergency airway protocol.']), _PccuSection('Major cautions', <String>['Hyperkalemia and cardiac arrest risk in susceptible neuromuscular disease/denervation states and after major burns/crush injury; malignant-hyperthermia trigger; bradycardia is more common in children and with repeat dosing.','Use only when contraindications have been considered and rescue capability is immediately available.']), _PccuSection('Sources', <String>['CPS procedural sedation rescue-medication table; local pediatric difficult-airway/RSI pathway.'])], 'SUCCINYLCHOLINE\n- RSI/rescue airway: 1â€“2 mg/kg IV when appropriate.\n- Paralysis onlyâ€”no sedation or analgesia.\n- Avoid/seek alternative in hyperkalemia-risk neuromuscular/denervation states, major burns/crush after risk develops, and malignant-hyperthermia susceptibility.\n- Watch bradycardia, especially repeat dosing.'),
_PccuEntry('Cisatracurium', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Role', <String>['Cisatracurium (Nimbex) is a nondepolarizing neuromuscular blocker with organ-independent Hofmann elimination, often useful when hepatic/renal dysfunction makes accumulation of other agents undesirable.','It provides no analgesia, anxiolysis, sedation or amnesia.']), _PccuSection('Typical pediatric IV reference doses', <String>['Bolus: commonly 0.1â€“0.2 mg/kg IV.','Continuous infusion: commonly about 1â€“3 mcg/kg/min, titrated to the minimum blockade required and local PICU protocol.']), _PccuSection('Important adverse effects', <String>['Prolonged neuromuscular weakness, immobility complications, corneal injury/pressure injury risk and awareness if sedation is inadequate. Histamine-related hypotension/bronchospasm is less common than with atracurium but remains possible.']), _PccuSection('Monitoring / care bundle', <String>['Ensure continuous analgesia + sedation, eye lubrication/closure care, pressure-area care, DVT/mobility considerations as appropriate, and train-of-four plus clinical assessment.']), _PccuSection('Sources', <String>['SCCM PANDEM; local PICU/pharmacy neuromuscular-blockade protocol.'])], 'CISATRACURIUM / NIMBEX\n- Bolus commonly 0.1â€“0.2 mg/kg IV.\n- Infusion commonly ~1â€“3 mcg/kg/min.\n- Organ-independent Hofmann elimination.\n- Paralysis only: maintain deep analgesia + sedation.\n- TOF + clinical assessment; eye/skin/pressure care.'),
_PccuEntry('Vecuronium', 'Sedation, Analgesia & Paralysis', <_PccuSection>[_PccuSection('Clinical overview', <String>['Vecuronium: nondepolarizing blocker with hepatic/renal dependence and risk of accumulation.','Always prescribe analgesia and sedation before or with paralysis.']), _PccuSection('Initial stabilization', <String>['Confirm indication, weight, airway plan, hemodynamics and concurrent sedatives.','Use a validated sedation/pain target and the lowest effective dose.']), _PccuSection('Disease-specific treatment / settings', <String>['Use local formulary bolus/infusion doses and smart-pump concentrations.','Daily reassessment and protocolized weaning reduce oversedation and withdrawal.']), _PccuSection('Monitoring', <String>['Continuous cardiorespiratory monitoring; pain/sedation score, BP, ventilation, bowel/bladder function and drug-specific adverse effects.']), _PccuSection('Expected response', <String>['Comfort, synchrony and procedure tolerance at the predefined target.']), _PccuSection('Failure criteria and escalation', <String>['Inadequate comfort, hypotension, respiratory depression, delirium, prolonged paralysis or escalating requirements.']), _PccuSection('Complications / cautions', <String>['Tolerance, withdrawal, delirium, ileus, hypotension and prolonged ventilation.']), _PccuSection('Sources and local verification', <String>['SCCM PANDEM pediatric guidelines; local sedation formulary.'])], 'VECURONIUM\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Vecuronium pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Hypernatremic dehydration', 'Fluids & Electrolytes', <_PccuSection>[_PccuSection('Clinical overview', <String>['Hypernatremic dehydration requires confirmation of severity, chronicity, symptoms, renal function and ongoing losses before correction.','Use trends and clinical context; avoid correcting a number in isolation.']), _PccuSection('Initial stabilization', <String>['Repeat/confirm critical results when safe, review ECG and medications, assess volume status and obtain strict intake/output.','Call nephrology/PCCU early for severe symptoms, oliguria/anuria or rapidly changing values.']), _PccuSection('Disease-specific treatment / settings', <String>['Correct hypernatremic dehydration using the dedicated calculator or local replacement protocol when available.','Account for enteral intake, carrier fluids, renal function and ongoing losses; use pharmacy-verified concentrations.']), _PccuSection('Monitoring', <String>['Serial electrolytes, renal function, ECG when relevant, urine output, fluid balance and neurologic status.']), _PccuSection('Expected response', <String>['Controlled correction with improving symptoms and no new electrolyte or volume complication.']), _PccuSection('Failure criteria and escalation', <String>['Neurologic symptoms, arrhythmia, worsening renal function, refractory abnormality or unsafe correction rate.']), _PccuSection('Complications / cautions', <String>['Overcorrection, arrhythmia, fluid overload, tissue injury from concentrated infusions and osmotic neurologic injury.']), _PccuSection('Sources and local verification', <String>['KDIGO pediatric principles; local electrolyte/renal protocol.'])], 'HYPERNATREMIC DEHYDRATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Hypernatremic dehydration pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Hyponatremia', 'Fluids & Electrolytes', <_PccuSection>[_PccuSection('Clinical overview', <String>['Hyponatremia requires confirmation of severity, chronicity, symptoms, renal function and ongoing losses before correction.','Use trends and clinical context; avoid correcting a number in isolation.']), _PccuSection('Initial stabilization', <String>['Repeat/confirm critical results when safe, review ECG and medications, assess volume status and obtain strict intake/output.','Call nephrology/PCCU early for severe symptoms, oliguria/anuria or rapidly changing values.']), _PccuSection('Disease-specific treatment / settings', <String>['Correct hyponatremia using the dedicated calculator or local replacement protocol when available.','Account for enteral intake, carrier fluids, renal function and ongoing losses; use pharmacy-verified concentrations.']), _PccuSection('Monitoring', <String>['Serial electrolytes, renal function, ECG when relevant, urine output, fluid balance and neurologic status.']), _PccuSection('Expected response', <String>['Controlled correction with improving symptoms and no new electrolyte or volume complication.']), _PccuSection('Failure criteria and escalation', <String>['Neurologic symptoms, arrhythmia, worsening renal function, refractory abnormality or unsafe correction rate.']), _PccuSection('Complications / cautions', <String>['Overcorrection, arrhythmia, fluid overload, tissue injury from concentrated infusions and osmotic neurologic injury.']), _PccuSection('Sources and local verification', <String>['KDIGO pediatric principles; local electrolyte/renal protocol.'])], 'HYPONATREMIA\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Hyponatremia pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently