        separatorBuilder: (_, __) => const SizedBox(height: 10),
        itemBuilder: (context, index) {
          final item = items[index];
          return Card(
            child: ListTile(
              leading: CircleAvatar(child: Icon(item.icon)),
              title: Text(item.title, style: const TextStyle(fontWeight: FontWeight.w800)),
              subtitle: Text(item.subtitle),
              trailing: const Icon(Icons.chevron_right),
              onTap: () => Navigator.of(context).push(
                MaterialPageRoute<void>(builder: (_) => item.screen),
              ),
            ),
          );
        },
      ),
    );
  }
}

class _PccuCategory { final String title; final IconData icon; final List<String> topics; const _PccuCategory(this.title, this.icon, this.topics); }
class _PccuSection { final String heading; final List<String> bullets; const _PccuSection(this.heading, this.bullets); }
class _PccuEntry {
  final String title; final String category; final List<_PccuSection> sections; final String copyPlan;
  const _PccuEntry(this.title, this.category, this.sections, this.copyPlan);
  String get searchText => sections.expand((s) => <String>[s.heading, ...s.bullets]).join(' ');
}

class PccuTopicScreen extends StatelessWidget {
  final String title;
  const PccuTopicScreen({super.key, required this.title});
  @override Widget build(BuildContext context) {
    final entry = _PccuScreenState.entry(title);
    return _PccuDetailScreen(entry: entry);
  }
}

class _PccuDetailScreen extends StatelessWidget {
  final _PccuEntry entry;
  const _PccuDetailScreen({required this.entry});
  @override Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text(entry.title)),
    body: ListView(padding: const EdgeInsets.all(16), children: <Widget>[
      Text(entry.category, style: Theme.of(context).textTheme.labelLarge),
      const SizedBox(height: 8),
      Card(color: Theme.of(context).colorScheme.errorContainer, child: const Padding(padding: EdgeInsets.all(14), child: Text('Initial decision supportâ€”not an automatic prescription. Apply current local protocols and obtain senior/PCCU support when indicated.'))),
      const SizedBox(height: 10),
      ...entry.sections.map((section) => Card(child: ExpansionTile(initiallyExpanded: section.heading == 'Initial approach / settings' || section.heading == 'Escalation triggers' || section.heading == 'Medication doses / settings', title: Text(section.heading, style: const TextStyle(fontWeight: FontWeight.w800)), children: section.bullets.map((b) => ListTile(leading: const Icon(Icons.check_circle_outline), title: Text(b))).toList()))),
      if (_relatedTools(entry.title).isNotEmpty) ...<Widget>[
        const SizedBox(height: 10),
        Text('Related tools', style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w900)),
        const SizedBox(height: 8),
        Wrap(spacing: 8, runSpacing: 8, children: _relatedTools(entry.title).map((tool) => ActionChip(avatar: Icon(tool.icon, size: 18), label: Text(tool.label), onPressed: () => tool.open(context))).toList()),
      ],
      const SizedBox(height: 10),
      FilledButton.icon(onPressed: () async { await Clipboard.setData(ClipboardData(text: entry.copyPlan)); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('PCCU plan copied'))); }, icon: const Icon(Icons.copy), label: const Text('Copy PCCU plan')),
    ]),
  );
}


class _RelatedTool {
  final String label; final IconData icon; final void Function(BuildContext) open;
  const _RelatedTool(this.label,this.icon,this.open);
}
List<_RelatedTool> _relatedTools(String title) {
  void openTopic(BuildContext c,String t)=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>PccuTopicScreen(title:t)));
  if (title == 'Severe asthma' || title == 'Status asthmaticus') return <_RelatedTool>[
    _RelatedTool('Continuous salbutamol',Icons.medication_liquid_outlined,(c)=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>const _AsthmaDoseCalculator()))),
    _RelatedTool('HFNC guidance',Icons.air,(c)=>openTopic(c,'High-flow nasal cannula')),
    _RelatedTool('NIV guidance',Icons.air,(c)=>openTopic(c,'Non-invasive ventilation troubleshooting')),
    _RelatedTool('Intubation',Icons.air,(c)=>openTopic(c,'Pediatric rapid-sequence intubation')),
    _RelatedTool('Ventilator settings',Icons.settings_input_component,(c)=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>const _VentilatorPresetCalculator()))),
    _RelatedTool('Ketamine',Icons.medication_outlined,(c)=>openTopic(c,'Ketamine')),
  ];
  if (title == 'DKA' || title == 'Cerebral edema in DKA') return <_RelatedTool>[
    _RelatedTool('Native DKA calculator',Icons.calculate_outlined,(c)=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>const DkaCalculatorScreen()))),
    _RelatedTool('Cerebral injury',Icons.psychology_outlined,(c)=>openTopic(c,'Cerebral edema in DKA')),
    _RelatedTool('Potassium replacement',Icons.science_outlined,(c)=>openTopic(c,'Hypokalemia')),
    _RelatedTool('Phosphate replacement',Icons.science_outlined,(c)=>openTopic(c,'Hypophosphatemia')),
    _RelatedTool('Fluid calculators',Icons.water_drop_outlined,(c)=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>const CalculatorsScreen()))),
  ];
  if (title == 'Septic shock') return <_RelatedTool>[
    _RelatedTool('Vasoactive calculator',Icons.calculate_outlined,(c)=>Navigator.of(c).push(MaterialPageRoute<void>(builder:(_)=>const _VasoactiveInfusionCalculator()))),
    _RelatedTool('Epinephrine',Icons.medication_outlined,(c)=>openTopic(c,'Epinephrine')),
    _RelatedTool('Norepinephrine',Icons.medication_outlined,(c)=>openTopic(c,'Norepinephrine')),
  ];
  if (title == 'Status epilepticus') return <_RelatedTool>[
    _RelatedTool('Refractory status',Icons.bolt,(c)=>openTopic(c,'Refractory status epilepticus')),
    _RelatedTool('Intubation',Icons.air,(c)=>openTopic(c,'Pediatric rapid-sequence intubation')),
  ];
  if (title == 'Lumbar puncture') return <_RelatedTool>[
    _RelatedTool('LP sedation',Icons.medication_liquid_outlined,(c)=>openTopic(c,'Lumbar puncture sedation')),
    _RelatedTool('Ketamine',Icons.medication_outlined,(c)=>openTopic(c,'Ketamine')),
    _RelatedTool('Propofol',Icons.medication_outlined,(c)=>openTopic(c,'Propofol')),
  ];
  if (title == 'Traumatic brain injury') return <_RelatedTool>[
    _RelatedTool('TBI sedation',Icons.medication_liquid_outlined,(c)=>openTopic(c,'TBI sedation & neuroprotection')),
    _RelatedTool('Intubation / RSI',Icons.air,(c)=>openTopic(c,'Intubation / RSI sedation')),
    _RelatedTool('Ketamine',Icons.medication_outlined,(c)=>openTopic(c,'Ketamine')),
    _RelatedTool('Fentanyl',Icons.medication_outlined,(c)=>openTopic(c,'Fentanyl')),
  ];
  if (title == 'Pediatric rapid-sequence intubation') return <_RelatedTool>[
